record.field:
# OAuth2 authentication for AgZoom
remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}
client_id = (cfg.get('client_id') or '').strip()
client_secret = (cfg.get('client_secret') or '').strip()
username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()
if not client_id or not client_secret or not username or not password:
    raise Exception("Missing AgZoom credentials: set client_id, client_secret, username and password in connection_params.")
url = (base_url or '').rstrip('/') + '/oauth/v2/token'
params = {
    'grant_type': 'password',
    'client_id': client_id,
    'client_secret': client_secret,
    'username': username,
    'password': password
}
resp = request_retry('GET', url, params=params)
if resp.status_code >= 400:
    raise Exception("OAuth2 login failed: %s %s" % (resp.status_code, resp.text))
j = resp.json() or {}
access_token = j.get('access_token') or ''
if not access_token:
    raise Exception("OAuth2 OK but no 'access_token' in response.")
bag['access_token'] = access_token
# Optional: store refresh_token if present
refresh_token = j.get('refresh_token')
if refresh_token:
    bag['refresh_token'] = refresh_token

# Action A: build sensors plan for AgZoom
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]
# Now iterate sensors using the map
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    sensor_code = (sensor_cfg.get('sensor_code') or '').strip()
    id = (sensor_cfg.get('id') or '').strip()
    if sensor_code and id:
        try:
            device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
        except Exception:
            device_cfg = {}
        agzoom_device_id = (device_cfg.get('agzoom_device_id') or '').strip()
        if agzoom_device_id:
            # Retrieve last_reading from map (no query per sensor)
            last_reading_time = last_readings_map.get(sensor.id)
            if last_reading_time:
                try:
                    initial_date = fields.Date.to_string(
                        fields.Datetime.from_string(last_reading_time) +
                        timedelta(days=1))
                except Exception:
                    initial_date = str(last_reading_time)[:10]
            else:
                start_cfg = (sensor_cfg.get('start_date') or device_cfg.get('start_date'))
                if start_cfg:
                    initial_date = start_cfg[:10]
                else:
                    year_str = today_str[:4]
                    initial_date = '%s-01-01' % year_str
            plan.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'agzoom_device_id': agzoom_device_id,
                'sensor_code': sensor_code,
                'id': id,
                'initial_date': initial_date,
            })
bag['sensors_plan'] = plan

Remote = self.remote_id access_token = bag.get('access_token') if not access_token: raise Exception('Missing AgZoom access_token in bag')
headers = {'Authorization': 'Bearer %s' % access_token, 'Accept': 'application/json'}
# Step 1: Get devices list from AgZoom userdevices_url = (bag.get('base_url') or Remote.base_url or '').rstrip('/') + '/api/userdevices' resp = request_retry('GET', userdevices_url, headers=headers, timeout=timeout) if resp.status_code >= 400: raise Exception('Error fetching devices: %s %s' % (resp.status_code, resp.text))
devices_response = resp.json() or {} status = devices_response.get('status', '-1') if status != '0': raise Exception('AgZoom API error status: %s' % status)
# Step 2: Build device list and fetch sensor details for each device devices_list = [] costumers = devices_response.get('costumers', []) for costumer in costumers: costumer_name = costumer.get('name', 'Unknown') fincas = costumer.get('fincas', []) for finca in fincas: finca_name = finca.get('name', 'Unknown') devices = finca.get('devices', []) for device in devices: device_id = device.get('id') device_name = device.get('name', 'Device %s' % device_id if device_id else 'Unnamed') location = device.get('location', '') battery = device.get('batteryLoad', '')
if device_id: # Step 3: Fetch sensor data for this device sensors_info = [] try: # Get recent data to extract sensor configuration # Use last 7 days to ensure we get at least some data from datetime import datetime, timedelta end_date = datetime.now() start_date = end_date - timedelta(days=7) end_date_str = end_date.strftime('%Y%m%d%H%M%S') start_date_str = start_date.strftime('%Y%m%d%H%M%S')
sensordata_url = (bag.get('base_url') or Remote.base_url or '').rstrip('/') + '/api/getsensordata/%s/date/%s/%s' % (device_id, end_date_str, start_date_str) sensor_resp = request_retry('GET', sensordata_url, headers=headers, timeout=timeout)
if sensor_resp.status_code < 400: sensor_payload = sensor_resp.json() or {} sensor_status = sensor_payload.get('status', '-1')
if sensor_status == '0': device_data = sensor_payload.get('device', {}) if device_data and isinstance(device_data, dict): sensors_array = device_data.get('sensors', [])
for sensor_item in sensors_array: sensor_code = sensor_item.get('code', '') sensor_type = sensor_item.get('type', '') sensor_port = sensor_item.get('port', '') sensor_depth = sensor_item.get('depth', '')
# Extract unique id from variables variables = sensor_item.get('variables', []) id_info = [] seen_id = set()
for variable in variables: id = variable.get('id', '') var_type = variable.get('type', '') var_id = variable.get('id', '') id_default = variable.get('id_default', '')
if id and id not in seen_id: seen_id.add(id) id_info.append({ 'id': id, 'type': var_type, 'id': var_id, 'id_default': id_default })
if sensor_code: sensors_info.append({ 'code': sensor_code, 'type': sensor_type, 'port': sensor_port, 'depth': sensor_depth, 'available_id': id_info }) except Exception as e: # If sensor data fetch fails, still include the device sensors_info = [{'error': 'Could not fetch sensor data: %s' % str(e)}]
devices_list.append({ 'agzoom_device_id': str(device_id), 'name': device_name, 'costumer': costumer_name, 'finca': finca_name, 'location': location, 'battery': battery, 'sensors': sensors_info })
# Sort by costumer, finca, then name devices_list.sort(key=lambda x: (x.get('costumer', ''), x.get('finca', ''), x.get('name', '')))
# Generate comprehensive JSON report report = { 'generated_at': str(fields.Datetime.now()), 'system_date': devices_response.get('systemDate', ''), 'total_devices': len(devices_list), 'devices': devices_list, 'configuration_guide': { 'device_params': { 'agzoom_device_id': 'Use the device ID from this report', 'start_date': 'YYYY-MM-DD format (e.g., 2025-10-13)' }, 'sensor_params': { 'sensor_code': 'Use the sensor code from sensors[].code', 'id': 'Use one of the available id from sensors[].available_id[].id', 'start_date': 'YYYY-MM-DD format (optional, inherits from device if not set)' } } }
# Create attachment json_str = json.dumps(report, ensure_ascii=False, indent=2, default=str) encoded = base64.b64encode(json_str.encode('utf-8')) fname = 'agzoom_devices_complete_%s.json' % fields.Datetime.now().replace(':','').replace('-','').replace(' ','_')
att = env['ir.attachment'].create({ 'name': fname, 'datas_fname': fname, 'datas': encoded, 'mimetype': 'application/json', 'res_model': 'remotecontrol', 'res_id': Remote.id })
Remote.message_post( body='[AgZoom] %s devices listed with complete sensor configuration' % len(devices_list), attachment_ids=[att.id] )
bag.clear() bag['total_devices'] = len(devices_list) bag['attachment_id'] = att.id
